import{_ as n,a0 as o,w as p,s,ao as d,I as i,x as a,a1 as t,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"如何在 Ubuntu/CentOS7.1/Fedora22 上安装 Plex  Media Server | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu/CentOS7.1/Fedora22 上安装 Plex  Media Server | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu/CentOS7.1/Fedora22 上安装 Plex  Media Server | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu/CentOS7.1/Fedora22 上安装 Plex  Media Server | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/Install Plex Media Server On Ubuntu or CentOS 7.1 or Fedora 22","title":"如何在 Ubuntu/CentOS7.1/Fedora22 上安装 Plex  Media Server","tag":"201507","desc":""},"relativePath":"201507/Install Plex Media Server On Ubuntu or CentOS 7.1 or Fedora 22.md","filePath":"[post].md"}'),x={name:"201507/Install Plex Media Server On Ubuntu or CentOS 7.1 or Fedora 22.md"};function u(b,e,m,h,P,S){const r=o("Link");return p(),s("div",null,[e[16]||(e[16]=d(`<h1 id="如何在-ubuntu-centos7-1-fedora22-上安装-plex-media-server" tabindex="-1">如何在 Ubuntu/CentOS7.1/Fedora22 上安装 Plex Media Server <a class="header-anchor" href="#如何在-ubuntu-centos7-1-fedora22-上安装-plex-media-server" aria-label="Permalink to “如何在 Ubuntu/CentOS7.1/Fedora22 上安装 Plex  Media Server”">​</a></h1><p>在本文中我们将会向你展示如何容易地在主流的最新Linux发行版上安装Plex Media Server。在Plex安装成功后你将可以使用你的中央式家庭媒体播放系统，该系统能让多个Plex播放器App共享它的媒体资源，并且该系统允许你设置你的环境，增加你的设备以及设置一个可以一起使用Plex的用户组。让我们首先在Ubuntu15.04上开始Plex的安装。</p><h3 id="基本的系统资源" tabindex="-1">基本的系统资源 <a class="header-anchor" href="#基本的系统资源" aria-label="Permalink to “基本的系统资源”">​</a></h3><p>系统资源主要取决于你打算用来连接服务的设备类型和数量， 所以根据我们的需求我们将会在一个单独的服务器上使用以下系统资源。</p><table width="666" style="height:181px;"><tbody><tr><td width="670" colspan="2"><b>Plex Media Server</b></td></tr><tr><td width="236"><b>基础操作系统</b></td><td width="425">Ubuntu 15.04 / CentOS 7.1 / Fedora 22 Work Station</td></tr><tr><td width="236"><b>Plex Media Server</b></td><td width="425">Version 0.9.12.3.1173-937aac3</td></tr><tr><td width="236"><b>RAM 和 CPU</b></td><td width="425">1 GB  , 2.0 GHZ</td></tr><tr><td width="236"><b>硬盘</b></td><td width="425">30 GB</td></tr></tbody></table><h3 id="在ubuntu-15-04上安装plex-media-server-0-9-12-3" tabindex="-1">在Ubuntu 15.04上安装Plex Media Server 0.9.12.3 <a class="header-anchor" href="#在ubuntu-15-04上安装plex-media-server-0-9-12-3" aria-label="Permalink to “在Ubuntu 15.04上安装Plex Media Server 0.9.12.3”">​</a></h3><p>我们现在准备开始在Ubuntu上安装Plex Media Server，让我们从下面的步骤开始来让Plex做好准备。</p><h4 id="步骤-1-系统更新" tabindex="-1">步骤 1: 系统更新 <a class="header-anchor" href="#步骤-1-系统更新" aria-label="Permalink to “步骤 1: 系统更新”">​</a></h4><p>用root权限登录你的服务器。确保你的系统是最新的，如果不是就使用下面的命令。</p><pre><code>root@ubuntu-15:~#apt-get update
</code></pre><h4 id="步骤-2-下载最新的plex-media-server包" tabindex="-1">步骤 2: 下载最新的Plex Media Server包 <a class="header-anchor" href="#步骤-2-下载最新的plex-media-server包" aria-label="Permalink to “步骤 2: 下载最新的Plex Media Server包”">​</a></h4>`,11)),i("p",null,[e[1]||(e[1]=a("创建一个新目录，用wget命令从",-1)),t(r,{href:"https://plex.tv/"},{default:l(()=>[...e[0]||(e[0]=[a("Plex官网",-1)])]),_:1}),e[2]||(e[2]=a("下载为Ubuntu提供的.deb包并放入该目录中。",-1))]),e[17]||(e[17]=d(`<pre><code>root@ubuntu-15:~# cd /plex/
root@ubuntu-15:/plex#
root@ubuntu-15:/plex# wget https://downloads.plex.tv/plex-media-server/0.9.12.3.1173-937aac3/plexmediaserver_0.9.12.3.1173-937aac3_amd64.deb
</code></pre><h4 id="步骤-3-安装plex-media-server的debian包" tabindex="-1">步骤 3: 安装Plex Media Server的Debian包 <a class="header-anchor" href="#步骤-3-安装plex-media-server的debian包" aria-label="Permalink to “步骤 3: 安装Plex Media Server的Debian包”">​</a></h4><p>现在在相同的目录下执行下面的命令来开始debian包的安装， 然后检查plexmediaserver服务的状态。</p><pre><code>root@ubuntu-15:/plex# dpkg -i plexmediaserver_0.9.12.3.1173-937aac3_amd64.deb
</code></pre><hr><pre><code>root@ubuntu-15:~# service plexmediaserver status
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/plex-status.png" alt="Plexmediaserver Service"></p><h3 id="在ubuntu-15-04上设置plex-media-web应用" tabindex="-1">在Ubuntu 15.04上设置Plex Media Web应用 <a class="header-anchor" href="#在ubuntu-15-04上设置plex-media-web应用" aria-label="Permalink to “在Ubuntu 15.04上设置Plex  Media Web应用”">​</a></h3><p>让我们在你的本地网络主机中打开web浏览器， 并用你的本地主机IP以及端口32400来打开Web界面，并完成以下步骤来配置Plex。</p><pre><code>http://172.25.10.179:32400/web
http://localhost:32400/web
</code></pre><h4 id="步骤-1-登录前先注册" tabindex="-1">步骤 1: 登录前先注册 <a class="header-anchor" href="#步骤-1-登录前先注册" aria-label="Permalink to “步骤 1: 登录前先注册”">​</a></h4><p>在你访问到Plex Media Server的Web界面之后， 确保注册并填上你的用户名和密码来登录。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/PMS-Login.png" alt="Plex Sign In"></p><h4 id="输入你的pin码来保护你的plex-media用户" tabindex="-1">输入你的PIN码来保护你的Plex Media用户#### <a class="header-anchor" href="#输入你的pin码来保护你的plex-media用户" aria-label="Permalink to “输入你的PIN码来保护你的Plex  Media用户####”">​</a></h4><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/333.png" alt="Plex User Pin"></p><p>现在你已经成功的在Plex Media下配置你的用户。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/3333.png" alt="Welcome To Plex"></p><h3 id="在设备上而不是本地服务器上打开plex-web应用" tabindex="-1">在设备上而不是本地服务器上打开Plex Web应用 <a class="header-anchor" href="#在设备上而不是本地服务器上打开plex-web应用" aria-label="Permalink to “在设备上而不是本地服务器上打开Plex Web应用”">​</a></h3><p>如我们在Plex Media主页看到的提示“你没有权限访问这个服务”。 这说明我们跟服务器计算机不在同个网络。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/33.png" alt="Plex Server Permissions"></p><p>现在我们需要解决这个权限问题，以便我们通过设备访问服务器而不是只能在服务器上访问。通过完成下面的步骤完成。</p><h3 id="设置ssh隧道使windows系统可以访问到linux服务器" tabindex="-1">设置SSH隧道使Windows系统可以访问到Linux服务器 <a class="header-anchor" href="#设置ssh隧道使windows系统可以访问到linux服务器" aria-label="Permalink to “设置SSH隧道使Windows系统可以访问到Linux服务器”">​</a></h3><p>首先我们需要建立一条SSH隧道以便我们访问远程服务器资源，就好像资源在本地一样。 这仅仅是必要的初始设置。</p><p>如果你正在使用Windows作为你的本地系统，Linux作为服务器，那么我们可以参照下图通过Putty来设置SSH隧道。 （LCTT译注: 首先要在Putty的Session中用Plex服务器IP配置一个SSH的会话，才能进行下面的隧道转发规则配置。 然后点击“Open”，输入远端服务器用户名密码， 来保持SSH会话连接。）</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/ssh-tunnel.png" alt="Plex SSH Tunnel"></p><p><strong>一旦你完成SSH隧道设置:</strong></p><p>打开你的Web浏览器窗口并在地址栏输入下面的URL。</p><pre><code>http://localhost:8888/web
</code></pre><p>浏览器将会连接到Plex服务器并且加载与服务器本地功能一致的Plex Web应用。 同意服务条款并开始。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/5.png" alt="Agree to Plex term"></p><p>现在一个功能齐全的Plex Media Server已经准备好添加新的媒体库、频道、播放列表等资源。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/8.png" alt="PMS Settings"></p><h3 id="在centos-7-1上安装plex-media-server-0-9-12-3" tabindex="-1">在CentOS 7.1上安装Plex Media Server 0.9.12.3 <a class="header-anchor" href="#在centos-7-1上安装plex-media-server-0-9-12-3" aria-label="Permalink to “在CentOS 7.1上安装Plex Media Server 0.9.12.3”">​</a></h3><p>我们将会按照上述在Ubuntu15.04上安装Plex Media Server的步骤来将Plex安装到CentOS 7.1上。</p><p>让我们从安装Plex Media Server开始。</p><h4 id="步骤1-安装plex-media-server" tabindex="-1">步骤1: 安装Plex Media Server <a class="header-anchor" href="#步骤1-安装plex-media-server" aria-label="Permalink to “步骤1: 安装Plex Media Server”">​</a></h4><p>为了在CentOS7.1上安装Plex Media Server，我们需要从Plex官网下载rpm安装包。 因此我们使用wget命令来将rpm包下载到一个新的目录下。</p><pre><code>[root@linux-tutorials ~]# cd /plex
[root@linux-tutorials plex]# wget https://downloads.plex.tv/plex-media-server/0.9.12.3.1173-937aac3/plexmediaserver-0.9.12.3.1173-937aac3.x86_64.rpm
</code></pre><h4 id="步骤2-安装rpm包" tabindex="-1">步骤2: 安装RPM包 <a class="header-anchor" href="#步骤2-安装rpm包" aria-label="Permalink to “步骤2: 安装RPM包”">​</a></h4><p>在完成安装包完整的下载之后， 我们将会使用rpm命令在相同的目录下安装这个rpm包。</p><pre><code>[root@linux-tutorials plex]# ls
plexmediaserver-0.9.12.3.1173-937aac3.x86_64.rpm
[root@linux-tutorials plex]# rpm -i plexmediaserver-0.9.12.3.1173-937aac3.x86_64.rpm
</code></pre><h4 id="步骤3-启动plexmediaservice" tabindex="-1">步骤3: 启动Plexmediaservice <a class="header-anchor" href="#步骤3-启动plexmediaservice" aria-label="Permalink to “步骤3: 启动Plexmediaservice”">​</a></h4><p>我们已经成功地安装Plex Media Server, 现在我们只需要重启它的服务然后让它永久地启用。</p><pre><code>[root@linux-tutorials plex]# systemctl start plexmediaserver.service
[root@linux-tutorials plex]# systemctl enable plexmediaserver.service
[root@linux-tutorials plex]# systemctl status plexmediaserver.service
</code></pre><h3 id="在centos-7-1上设置plex-media-web应用" tabindex="-1">在CentOS-7.1上设置Plex Media Web应用 <a class="header-anchor" href="#在centos-7-1上设置plex-media-web应用" aria-label="Permalink to “在CentOS-7.1上设置Plex  Media Web应用”">​</a></h3><p>现在我们只需要重复在Ubuntu上设置Plex Web应用的所有步骤就可以了。 让我们在Web浏览器上打开一个新窗口并用localhost或者Plex服务器的IP来访问Plex Media Web应用。</p><pre><code>http://172.20.3.174:32400/web
http://localhost:32400/web
</code></pre><p>为了获取服务的完整权限你需要重复创建SSH隧道的步骤。 在你用新账户注册后我们将可以访问到服务的所有特性，并且可以添加新用户、添加新的媒体库以及根据我们的需求来设置它。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/plex-devices-centos.png" alt="Plex Device Centos"></p><h3 id="在fedora-22工作站上安装plex-media-server-0-9-12-3" tabindex="-1">在Fedora 22工作站上安装Plex Media Server 0.9.12.3 <a class="header-anchor" href="#在fedora-22工作站上安装plex-media-server-0-9-12-3" aria-label="Permalink to “在Fedora 22工作站上安装Plex Media Server 0.9.12.3”">​</a></h3><p>下载和安装Plex Media Server步骤基本跟在CentOS 7.1上安装的步骤一致。我们只需要下载对应的rpm包然后用rpm命令来安装它。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/plex-on-fedora.png" alt="PMS Installation"></p><h3 id="在fedora-22工作站上配置plex-media-web应用" tabindex="-1">在Fedora 22工作站上配置Plex Media Web应用 <a class="header-anchor" href="#在fedora-22工作站上配置plex-media-web应用" aria-label="Permalink to “在Fedora 22工作站上配置Plex  Media Web应用”">​</a></h3><p>我们在（与Plex服务器）相同的主机上配置Plex Media Server，因此不需要设置SSH隧道。只要在你的Fedora 22工作站上用Plex Media Server的默认端口号32400打开Web浏览器并同意Plex的服务条款即可。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/Plex-Terms.png" alt="Plex Agreement"></p><p><em>欢迎来到Fedora 22工作站上的Plex Media Server</em></p><p>让我们用你的Plex账户登录，并且开始将你喜欢的电影频道添加到媒体库、创建你的播放列表、添加你的图片以及享用更多其他的特性。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/06/create-library.png" alt="Plex Add Libraries"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>我们已经成功完成Plex Media Server在主流Linux发行版上安装和配置。Plex Media Server永远都是媒体管理的最佳选择。 它在跨平台上的设置是如此的简单，就像我们在Ubuntu,CentOS以及Fedora上的设置一样。它简化了你组织媒体内容的工作，并将媒体内容“流”向其他计算机以及设备以便你跟你的朋友分享媒体内容。</p><hr>`,61)),i("p",null,[e[4]||(e[4]=a("via: ",-1)),t(r,{href:"http://linoxide.com/tools/install-plex-media-server-ubuntu-centos-7-1-fedora-22/"},{default:l(()=>[...e[3]||(e[3]=[a("http://linoxide.com/tools/install-plex-media-server-ubuntu-centos-7-1-fedora-22/",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=a("作者：",-1)),t(r,{href:"http://linoxide.com/author/kashifs/"},{default:l(()=>[...e[5]||(e[5]=[a("Kashif Siddique",-1)])]),_:1}),e[9]||(e[9]=a(" 译者：",-1)),t(r,{href:"https://github.com/dingdongnigetou"},{default:l(()=>[...e[6]||(e[6]=[a("dingdongnigetou",-1)])]),_:1}),e[10]||(e[10]=a(" 校对：",-1)),t(r,{href:"https://github.com/wxy"},{default:l(()=>[...e[7]||(e[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=a("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[11]||(e[11]=[a("LCTT",-1)])]),_:1}),e[14]||(e[14]=a(" 原创翻译，",-1)),t(r,{href:"https://linux.cn/"},{default:l(()=>[...e[12]||(e[12]=[a("Linux中国",-1)])]),_:1}),e[15]||(e[15]=a(" 荣誉推出",-1))])])}const M=n(x,[["render",u]]);export{g as __pageData,M as default};
